package com.sucharu.sucharupro.domain.service.vendor

import com.sucharu.sucharupro.data.datasource.FakeVendorDataSource
import com.sucharu.sucharupro.data.repository.VendorRepositoryImpl
import com.sucharu.sucharupro.domain.model.common.DomainResult
import com.sucharu.sucharupro.domain.model.vendor.VendorCategory
import com.sucharu.sucharupro.domain.model.vendor.VendorStatus
import com.sucharu.sucharupro.domain.model.vendor.VendorType
import kotlinx.coroutines.runBlocking
import org.junit.Assert.*
import org.junit.Before
import org.junit.Test

class VendorServiceTest {

    private lateinit var fakeDataSource: FakeVendorDataSource
    private lateinit var vendorRepository: VendorRepositoryImpl
    private lateinit var vendorService: VendorService

    @Before
    fun setUp() {
        fakeDataSource = FakeVendorDataSource()
        vendorRepository = VendorRepositoryImpl(fakeDataSource)
        vendorService = VendorServiceImpl(vendorRepository)
    }

    @Test
    fun testCreateVendorSuccess() = runBlocking {
        val res = vendorService.createVendor(
            projectId = "PRJ-01",
            vendorName = "National Foiling & Die Cutting",
            vendorCode = "VND-FOIL-01",
            legalName = "National Foiling Ltd.",
            vendorType = VendorType.PRODUCTION_VENDOR,
            vendorCategory = VendorCategory.FINISHING,
            status = VendorStatus.ACTIVE,
            primaryContactName = "Jashim",
            primaryPhone = "+8801999887766",
            primaryEmail = "jashim@nationalfoil.com",
            notes = "Cold and hot foil stamping services.",
            createdBy = "admin"
        )

        assertTrue(res is DomainResult.Success)
        val v = (res as DomainResult.Success).data
        assertEquals("National Foiling & Die Cutting", v.vendorName)
        assertEquals("VND-FOIL-01", v.vendorCode)
        assertEquals(VendorCategory.FINISHING, v.vendorCategory)
        assertTrue(v.vendorId.isNotBlank())
    }

    @Test
    fun testAutoGeneratedVendorCodeIfNull() = runBlocking {
        val res = vendorService.createVendor(
            projectId = "PRJ-01",
            vendorName = "Auto Code Vendor"
        )

        assertTrue(res is DomainResult.Success)
        val v = (res as DomainResult.Success).data
        assertTrue(v.vendorCode.startsWith("VND-"))
    }

    @Test
    fun testCreateDuplicateVendorCodeFails() = runBlocking {
        vendorService.createVendor(
            projectId = "PRJ-01",
            vendorName = "Vendor A",
            vendorCode = "VND-DUP"
        )

        val res2 = vendorService.createVendor(
            projectId = "PRJ-01",
            vendorName = "Vendor B",
            vendorCode = "VND-DUP"
        )

        assertTrue(res2 is DomainResult.Error)
        assertTrue((res2 as DomainResult.Error).message.contains("already exists"))
    }

    @Test
    fun testUpdateVendor() = runBlocking {
        val created = (vendorService.createVendor(
            projectId = "PRJ-01",
            vendorName = "Original Name",
            vendorCode = "VND-UP-01"
        ) as DomainResult.Success).data

        val updateRes = vendorService.updateVendor(
            projectId = "PRJ-01",
            vendorId = created.vendorId,
            vendorName = "Updated Name",
            legalName = "Updated Legal Entity Ltd.",
            updatedBy = "manager"
        )

        assertTrue(updateRes is DomainResult.Success)
        val updated = (updateRes as DomainResult.Success).data
        assertEquals("Updated Name", updated.vendorName)
        assertEquals("Updated Legal Entity Ltd.", updated.legalName)
        assertEquals(2L, updated.version)
    }

    @Test
    fun testUpdateStatusToArchivedAndDisallowFurtherModifications() = runBlocking {
        val created = (vendorService.createVendor(
            projectId = "PRJ-01",
            vendorName = "To Archive",
            vendorCode = "VND-ARCH-01"
        ) as DomainResult.Success).data

        val archRes = vendorService.updateStatus(
            projectId = "PRJ-01",
            vendorId = created.vendorId,
            newStatus = VendorStatus.ARCHIVED,
            updatedBy = "admin"
        )
        assertTrue(archRes is DomainResult.Success)
        assertEquals(VendorStatus.ARCHIVED, (archRes as DomainResult.Success).data.status)

        // Attempting to update an archived vendor fails
        val failUpdate = vendorService.updateVendor(
            projectId = "PRJ-01",
            vendorId = created.vendorId,
            vendorName = "Should Fail"
        )
        assertTrue(failUpdate is DomainResult.Error)
        assertTrue((failUpdate as DomainResult.Error).message.contains("Cannot modify archived vendor"))

        // Attempting to transition status out of archived fails
        val failTransition = vendorService.updateStatus(
            projectId = "PRJ-01",
            vendorId = created.vendorId,
            newStatus = VendorStatus.ACTIVE
        )
        assertTrue(failTransition is DomainResult.Error)
        assertTrue((failTransition as DomainResult.Error).message.contains("Cannot transition status from ARCHIVED"))
    }
}
